import { Component, h, Prop, ComponentInterface, Host } from '@stencil/core';
import { StatusIconVariant, StatusIconSize } from './types';
import { ks } from '@fe-infra/keystone-design-tokens';
import {
  KsIconFilledCaution,
  KsIconFilledCheck,
  KsIconFilledDisapproval,
  KsIconFilledInProgress,
  KsIconFilledInfo,
  KsIconFilledLightbulb,
  KsIconFilledLimitedApproval,
  KsIconFilledWarning,
} from '@fe-infra/keystone-icons-stencil';

const prefix = 'status-icon';

@Component({
  tag: 'ks-status-icon',
  shadow: true,
  styleUrl: 'index.scss',
})
export class KsStatusIcon implements ComponentInterface {
  /** Defines the visual variant of the status icon. Can be one of the following values: `"disapproval"`, `"error"`, `"inProgress"`, `"info"`, `"limitedApproval"`, `"neutral"`, `"success"`, `"successLow"`, `"suggestion"` or `"warning"`. */
  @Prop() variant: StatusIconVariant = 'info';
  /** Specifies the size of the status icon. Can be either `"md"` or `"sm"`. */
  @Prop() size: StatusIconSize = 'md';
  /** Adds a one-pixel border around the status icon, to improve visual accessibility in background images. */
  @Prop() bordered = false;

  private getVariantIcon() {
    const MEDIUM_SIZE = 24;
    const SMALL_SIZE = 16;
    const size = this.size === 'md' ? MEDIUM_SIZE : SMALL_SIZE;
    switch (this.variant) {
      case 'suggestion':
        return (
          <KsIconFilledLightbulb
            size={size}
            color={ks.color.support.fillLow}
            innerColor={ks.color.support.onFillLow}
          ></KsIconFilledLightbulb>
        );
      case 'error':
        return (
          <KsIconFilledCaution
            size={size}
            color={ks.color.error.fillLow}
            innerColor={ks.color.error.onFillLow}
          ></KsIconFilledCaution>
        );
      case 'warning':
        return (
          <KsIconFilledWarning
            size={size}
            color={ks.color.warning.fillLow}
            innerColor={ks.color.warning.onFillLow}
          ></KsIconFilledWarning>
        );
      case 'info':
        return (
          <KsIconFilledInfo
            size={size}
            color={ks.color.primary.fillLow}
            innerColor={ks.color.primary.onFillLow}
          ></KsIconFilledInfo>
        );
      case 'success':
        return (
          <KsIconFilledCheck
            size={size}
            color={ks.color.success.fillLow}
            innerColor={ks.color.success.onFillLow}
          ></KsIconFilledCheck>
        );
      case 'successLow':
        return (
          <KsIconFilledCheck
            size={size}
            color={ks.color.neutral.fillLow}
            innerColor={ks.color.neutral.onFillLow}
          ></KsIconFilledCheck>
        );
      case 'inProgress':
        return (
          <KsIconFilledInProgress
            size={size}
            color={ks.color.primary.fillLow}
            innerColor={ks.color.primary.onFillLow}
          ></KsIconFilledInProgress>
        );
      case 'disapproval':
        return <KsIconFilledDisapproval size={size} color={ks.color.neutral.fillLow}></KsIconFilledDisapproval>;
      case 'limitedApproval':
        return <KsIconFilledLimitedApproval size={size} color={ks.color.neutral.fillLow}></KsIconFilledLimitedApproval>;
      default:
        return (
          <KsIconFilledInfo
            size={size}
            color={ks.color.neutral.fillLow}
            innerColor={ks.color.neutral.onFillLow}
          ></KsIconFilledInfo>
        );
    }
  }

  render() {
    const borderStyle = this.bordered ? { '--ks-comp-icon-color-border': ks.color.neutral.onFill } : undefined;

    return (
      <Host class="KsStatusIcon" role="status">
        <div class={prefix} style={borderStyle}>
          {this.getVariantIcon()}
        </div>
      </Host>
    );
  }
}
